# pdd2uipath bridge worker (PowerShell). Generated by `pdd2uipath bridge install`.
# Polls <workspace>\.pdd2uipath-bridge\jobs\*.json, executes allowlisted `uip` commands on
# paths inside the workspace root, writes results\<id>.json atomically, and touches
# heartbeat.json every few seconds. Stop with Ctrl+C or by creating the STOP file.
#
# Start:  powershell -NoProfile -ExecutionPolicy Bypass -File "<this file>"
# No Python is needed on Windows.

param()
$ErrorActionPreference = 'Continue'
$Root = Split-Path -Parent $MyInvocation.MyCommand.Definition
$WorkspaceRoot = '__WORKSPACE_ROOT__'
$Uip = @(__UIP_COMMAND__)
$PollMs = __POLL_MS__
$HeartbeatEveryS = 3

$AllowedRpa = @('templates','init','restore','packages','activities','validate','build','analyze','analyzer-rules','studio','instances','get-object-repository','workflow-examples')
$AllowedLogin = @('status','which')
$PathFlags = @('--project-dir','--location','--studio-dir','--robot-dir','--nuget-sources-config-path','--packages-file','--log-file','--detailed-log-path','--governance-file-path','--policy-file','--input-arguments-file','--field-values-file','--repository-path','--file','-f')
$PositionalVerbs = @('build','restore','analyze','pack')
$Forbidden = [char[]]'&|<>^"%!' + [char]13 + [char]10 + [char]0

$JobsDir = Join-Path $Root 'jobs'
$ResultsDir = Join-Path $Root 'results'
$Heartbeat = Join-Path $Root 'heartbeat.json'
$StopFile = Join-Path $Root 'STOP'
New-Item -ItemType Directory -Force -Path $JobsDir, $ResultsDir | Out-Null

function Write-Atomic([string]$Path, [string]$Text) {
  $tmp = "$Path.tmp"
  [System.IO.File]::WriteAllText($tmp, $Text, (New-Object System.Text.UTF8Encoding($false)))
  Move-Item -LiteralPath $tmp -Destination $Path -Force
}

function Touch-Heartbeat {
  $payload = @{ worker = 'ps1'; pid = $PID; ts = (Get-Date).ToUniversalTime().ToString('o'); root = $WorkspaceRoot } | ConvertTo-Json -Compress
  Write-Atomic $Heartbeat $payload
}

function Test-Inside([string]$RootPath, [string]$Path) {
  $r = [System.IO.Path]::GetFullPath($RootPath).TrimEnd('\').ToLowerInvariant()
  try { $p = [System.IO.Path]::GetFullPath($Path).TrimEnd('\').ToLowerInvariant() } catch { return $false }
  return ($p -eq $r) -or $p.StartsWith($r + '\')
}

function Test-Job($Job) {
  # Returns $null when valid, else the rejection reason.
  $argv = @($Job.argv)
  if ($argv.Count -eq 0) { return 'empty argv' }
  foreach ($tok in $argv) {
    if (-not ($tok -is [string])) { return 'argv tokens must be strings' }
    if ($tok.IndexOfAny($Forbidden) -ge 0) { return "token '$tok' contains forbidden characters" }
  }
  $head = $argv[0]
  switch ($head) {
    'rpa'       { if ($argv.Count -lt 2 -or $AllowedRpa -notcontains $argv[1]) { return "uip rpa $($argv[1]) is not allowlisted" } }
    'login'     { if ($argv.Count -lt 2 -or $AllowedLogin -notcontains $argv[1]) { return "uip login $($argv[1]) is not allowlisted" } }
    '--version' { }
    '--help'    { }
    default     { return "uip $head is not allowlisted" }
  }
  if (-not (Test-Inside $WorkspaceRoot $Job.cwd)) { return "cwd '$($Job.cwd)' is outside the workspace root" }
  $verb = if ($head -eq 'rpa' -and $argv.Count -gt 1) { $argv[1] } else { $null }
  $positionalSeen = $false
  for ($i = 0; $i -lt $argv.Count; $i++) {
    $tok = $argv[$i]
    if ($PathFlags -contains $tok -and $i + 1 -lt $argv.Count) {
      if (-not (Test-Inside $WorkspaceRoot $argv[$i + 1])) { return "$tok '$($argv[$i + 1])' is outside the workspace root" }
      $i++; continue
    }
    if ($tok -eq '--file-path' -and $i + 1 -lt $argv.Count) {
      $v = $argv[$i + 1]
      if ($v.Length -gt 1 -and $v[1] -eq ':' -and -not (Test-Inside $WorkspaceRoot $v)) { return "--file-path '$v' is outside the workspace root" }
      $i++; continue
    }
    if ($PositionalVerbs -contains $verb -and $i -gt 1 -and -not $positionalSeen -and -not $tok.StartsWith('-') -and ($tok -match '[\\/]' -or $tok -match '^[A-Za-z]:')) {
      if ($PathFlags -notcontains $argv[$i - 1]) {
        if (-not (Test-Inside $WorkspaceRoot $tok)) { return "project path '$tok' is outside the workspace root" }
        $positionalSeen = $true
      }
    }
  }
  return $null
}

function Invoke-Uip([string]$Cwd, [string[]]$ArgList, [int]$TimeoutS, [string]$Out, [string]$Err) {
  $exe = $Uip[0]; $pre = @(); if ($Uip.Count -gt 1) { $pre = $Uip[1..($Uip.Count - 1)] }
  if ($exe -match '\.(cmd|bat)$') { $exe = 'cmd.exe'; $pre = @('/c', $Uip[0]) + $pre }
  $quoted = ($pre + $ArgList) | ForEach-Object { '"' + $_ + '"' }
  $p = Start-Process -FilePath $exe -ArgumentList $quoted -WorkingDirectory $Cwd -NoNewWindow -PassThru -RedirectStandardOutput $Out -RedirectStandardError $Err
  $null = $p.Handle  # cache the handle, otherwise ExitCode stays null on Windows PowerShell 5.1
  $deadline = (Get-Date).AddSeconds([Math]::Max($TimeoutS, 30))
  while (-not $p.HasExited) {
    Start-Sleep -Milliseconds 500
    Touch-Heartbeat
    if ((Get-Date) -gt $deadline) { try { $p.Kill() } catch {}; return @{ exit = 124; reason = "timeout after ${TimeoutS}s" } }
  }
  $p.WaitForExit()
  $code = $p.ExitCode
  if ($null -eq $code) { $code = 1 }
  return @{ exit = [int]$code; reason = '' }
}

function Process-Job([System.IO.FileInfo]$File) {
  $id = $File.BaseName
  $started = (Get-Date).ToUniversalTime().ToString('o')
  $outFile = "$id.out"; $errFile = "$id.err"
  $result = @{ schema = 'pdd2uipath.bridge.result/1'; id = $id; status = 'ok'; exit_code = 0; stdout_file = $outFile; stderr_file = $errFile; started = $started; finished = ''; worker = 'ps1'; reason = '' }
  try {
    $job = Get-Content -LiteralPath $File.FullName -Raw -Encoding UTF8 | ConvertFrom-Json
    if ($job.schema -ne 'pdd2uipath.bridge.job/1') { throw "unsupported job schema '$($job.schema)'" }
    $reason = Test-Job $job
    if ($reason) {
      $result.status = 'rejected'; $result.exit_code = 126; $result.reason = $reason
      Write-Host "[$id] REJECTED: $reason"
    } else {
      Write-Host "[$id] uip $($job.argv -join ' ')"
      $r = Invoke-Uip $job.cwd ([string[]]$job.argv) ([int]$job.timeout_s) (Join-Path $ResultsDir $outFile) (Join-Path $ResultsDir $errFile)
      $result.exit_code = $r.exit
      if ($r.reason) { $result.status = 'error'; $result.reason = $r.reason }
      Write-Host "[$id] exit $($r.exit)"
    }
  } catch {
    $result.status = 'error'; $result.exit_code = 125; $result.reason = "malformed job: $($_.Exception.Message)"
    Write-Host "[$id] ERROR: $($result.reason)"
  }
  $result.finished = (Get-Date).ToUniversalTime().ToString('o')
  Write-Atomic (Join-Path $ResultsDir "$id.json") ($result | ConvertTo-Json -Compress)
  Remove-Item -LiteralPath $File.FullName -Force -ErrorAction SilentlyContinue
  Remove-Item -LiteralPath (Join-Path $JobsDir "$id.args") -Force -ErrorAction SilentlyContinue
}

Write-Host "pdd2uipath bridge worker (PowerShell) pid $PID"
Write-Host "  workspace : $WorkspaceRoot"
Write-Host "  bridge    : $Root"
Write-Host "  uip       : $($Uip -join ' ')"
Write-Host "  allowlist : uip rpa {$($AllowedRpa -join ',')} | uip login {status,which} | uip --version"
Write-Host "Press Ctrl+C to stop (or create $StopFile)."
$lastBeat = Get-Date
Touch-Heartbeat
while ($true) {
  if (Test-Path -LiteralPath $StopFile) { Write-Host 'STOP file found, exiting.'; Remove-Item -LiteralPath $StopFile -Force -ErrorAction SilentlyContinue; break }
  $jobs = Get-ChildItem -LiteralPath $JobsDir -Filter '*.json' -File -ErrorAction SilentlyContinue | Sort-Object LastWriteTime, Name
  foreach ($j in $jobs) { Process-Job $j; Touch-Heartbeat }
  if (((Get-Date) - $lastBeat).TotalSeconds -ge $HeartbeatEveryS) { Touch-Heartbeat; $lastBeat = Get-Date }
  Start-Sleep -Milliseconds $PollMs
}
